const page = figma.root.children.find(p => p.id === '0:1');
await figma.setCurrentPageAsync(page);
const out = [];
function walk(n, depth){
  if (n.type === 'TEXT') out.push({i:n.id, n:n.name, t:n.characters, fs:n.fontSize, f:n.fontName, w:n.absoluteBoundingBox&&n.absoluteBoundingBox.width});
  if ('children' in n) for (const c of n.children) walk(c, depth+1);
}
for (const c of page.children) walk(c,0);
return JSON.stringify(out, null, 1);

