const page = figma.root.children.find(p => p.id === '1:2');
await figma.setCurrentPageAsync(page);
const out = [];
function walk(n, d){
  out.push({id:n.id, n:n.name, t:n.type, fs:n.fontSize, fc:n.fills && n.fills[0] && n.fills[0].color});
  if ('children' in n) for (const c of n.children) walk(c,d+1);
}
for (const c of page.children) walk(c);
return JSON.stringify(out);

const page = figma.root.children.find(p => p.id === '1:3');
await figma.setCurrentPageAsync(page);
const out = [];
function walk(n){
  out.push({id:n.id, n:n.name, t:n.type, w:n.width, h:n.height});
  if ('children' in n) for (const c of n.children) walk(c);
}
for (const c of page.children) walk(c);
return JSON.stringify(out);

const page = figma.root.children.find(p => p.id === '1:4');
await figma.setCurrentPageAsync(page);
const out = [];
function walk(n){
