function rgba(hex,op){const h=hex.replace('#','');const a=op===undefined?1:op;return {r:parseInt(h.substr(0,2),16)/255,g:parseInt(h.substr(2,2),16)/255,b:parseInt(h.substr(4,2),16)/255,a:a}}
function solid(hex,op){return {type:'SOLID',color:rgba(hex,op)}}
function T(chars,size,style,color,o){o=o||{};
  const t=figma.createText(); t.fontName={family:'Plus Jakarta Sans',style};
  t.characters=chars; t.fontSize=size; t.fills=[solid(color)];
  t.lineHeight={unit:'PIXELS',value:o.lh||Math.round(size*1.4)};
  if(o.ls!==undefined) t.letterSpacing={unit:'PERCENT',value:o.ls};
  if(o.w){t.textAutoResize='HEIGHT'; t.resize(o.w,10);}
  if(o.upper) t.textCase='UPPER';
  t.name=o.name||chars.slice(0,40); return t;
}
function variant(id,idx){let n=figma.getNodeById(id); if(n.type==='COMPONENT_SET') n=n.children[idx||0]; return n;}
function inst(id,size,color,idx){const i=variant(id,idx).createInstance(); i.rescale(size/Math.max(i.width,i.height)); if(color) i.findAll(n=>'fills' in n).forEach(v=>{try{v.fills=[solid(color)]}catch(e){}}); return i;}
function box(name,w,h,o){o=o||{}; const f=figma.createFrame(); f.name=name; f.resize(w,h); f.fills=o.fill?[solid(o.fill)]:[]; f.strokes=[];
  if(o.radius!==undefined) f.cornerRadius=o.radius;
  if(o.stroke){f.strokes=[solid(o.stroke)]; f.strokeWeight=1; f.strokeAlign='INSIDE';}
  f.clipsContent=o.clip===undefined?true:o.clip; return f;}
function lbox(name,w,h,o){o=o||{}; const f=box(name,w,h,o);
  f.layoutMode=o.dir||'VERTICAL'; f.itemSpacing=o.gap||0;
  f.primaryAxisSizingMode=o.pw||'FIXED'; f.counterAxisSizingMode=o.cw||'FIXED';
  f.paddingTop=o.pt||0; f.paddingBottom=o.pb||0; f.paddingLeft=o.pl||0; f.paddingRight=o.pr||0;
  f.primaryAxisAlignItems=o.pa||'MIN'; f.counterAxisAlignItems=o.ca||'MIN'; return f;}
