const page=figma.root.children.find(p=>p.id==='4:2');
await figma.setCurrentPageAsync(page);
const root=page.findOne(n=>n.name==='01_Home');
const issues=[];
function walk(n,anc){
  const bb=n.absoluteBoundingBox;
  if(!bb) return;
  if('overflow' in n) {}
  if(n.layoutMode&&n.layoutMode!=='NONE'){
    const ch=n.children;
    if(n.primaryAxisSizingMode==='FIXED'){
      const sum = (n.layoutMode==='VERTICAL'?n.paddingTop+n.paddingBottom:n.paddingLeft+n.paddingRight) + ch.reduce((a,c)=>a+c.height,0) + Math.max(0,ch.length-1)*n.itemSpacing;
      const avail = n.layoutMode==='VERTICAL'?n.height:n.width;
      if(sum>avail+1) issues.push({type:'OVERFLOW',node:n.name,id:n.id,path:anc,need:Math.round(sum),have:Math.round(avail)});
    }
  }
  if(n.type==='TEXT'){
    const p=n.parent;
    if(p && p.absoluteBoundingBox && bb.x < p.absoluteBoundingBox.x-1) issues.push({type:'TEXT_LEFT_OF_PARENT',node:n.name,text:n.characters.slice(0,40),id:n.id});
    if(n.textAutoResize==='HEIGHT' && p && p.layoutMode==='HORIZONTAL'){}
  }
  if('children' in n) for(const c of n.children) walk(c, anc.concat(n.name));
}
walk(root,[]);
const secOut=root.children.map(c=>({name:c.name,y:Math.round(c.y),h:Math.round(c.height),kids:c.children.length}));
// text inventory count
let texts=0; root.findAll(n=>n.type==='TEXT').forEach(()=>texts++);
return JSON.stringify({issues:issues.slice(0,40),issueCount:issues.length,sections:secOut,textCount:texts});

